INSERT INTO course_notes (topic, content) VALUES
('Python Basics', 'Python is a dynamically typed language. Variables do not require explicit type declarations, and types are inferred at runtime.'),
('Data Structures', 'Lists in Python are ordered and mutable. Tuples are ordered but immutable. Dictionaries store key-value pairs and are unordered by insertion in older Python versions but preserve insertion order since Python 3.7.'),
('Object-Oriented Programming', 'Classes define blueprints for objects. Inheritance allows a child class to reuse and extend behavior from a parent class using the extends keyword in most languages, or class Child(Parent) in Python.'),
('Databases', 'PostgreSQL is a relational database that uses SQL. Primary keys uniquely identify rows, and foreign keys create relationships between tables.'),
('Machine Learning', 'Overfitting occurs when a model memorizes training data instead of learning generalizable patterns, causing a gap between training accuracy and test accuracy.');
